{
  "image_summary": "该图表对比了2022至2026财年Netflix与迪士尼娱乐分部的营业收入规模及其同比增长率，展示了流媒体巨头间的营收差距与增长趋势。",
  "chart_type": "双轴图（柱状图+折线图组合）",
  "title_text": "迪士尼娱乐分部营业收入情况",
  "footer_text": "数据来源：公司公告\n注：迪士尼的财年为前一公历年10月开始，2026财年迪士尼使用2025年10月开始9个月数据，奈飞使用2026年1月开始6个月数据。",
  "axes": {
    "x_label": "财年 (FY)",
    "y_label": "左侧：营业收入（亿美元）；右侧：同比增长率 (%)",
    "x_categories": ["FY2022", "FY2023", "FY2024", "FY2025", "FY2026"],
    "y_range_or_categories": ["0-500 (亿美元)", "0%-18%"]
  },
  "series": [
    {
      "name": "NETFLIX营业收入",
      "color": "#fc8166",
      "data_points": [["FY2022", 316], ["FY2023", 337], ["FY2024", 390], ["FY2025", 452]],
      "meaning": "Netflix在对应财年的总营业收入"
    },
    {
      "name": "迪士尼娱乐分部营业收入",
      "color": "#8bd4f0",
      "data_points": [["FY2022", 396], ["FY2023", 406], ["FY2024", 412], ["FY2025", 425]],
      "meaning": "迪士尼娱乐分部在对应财年的营业收入"
    },
    {
      "name": "NETFLIX营收同比增长",
      "color": "#e85d45",
      "data_points": [["FY2023", "6.67%"], ["FY2024", "15.65%"], ["FY2025", "15.85%"], ["FY2026", "14.74%"]],
      "meaning": "Netflix营业收入的同比增长率"
    },
    {
      "name": "迪士尼娱乐分部营收同比增长",
      "color": "#4a90e2",
      "data_points": [["FY2022", "2.69%"], ["FY2023", null], ["FY2024", "1.36%"], ["FY2025", "3.11%"], ["FY2026", "7.47%"]],
      "meaning": "迪士尼娱乐分部营业收入的同比增长率"
    }
  ],
  "table_data": {
    "headers": ["财年", "Netflix收入(亿)", "迪士尼娱乐收入(亿)", "Netflix增速", "迪士尼娱乐增速"],
    "rows": [
      ["FY2022", "316", "396", "-", "2.69%"],
      ["FY2023", "337", "406", "6.67%", "-"],
      ["FY2024", "390", "412", "15.65%", "1.36%"],
      ["FY2025", "452", "425", "15.85%", "3.11%"],
      ["FY2026", "-", "-", "14.74%", "7.47%"]
    ]
  },
  "color_encoding": [
    {"color": "#fc8166", "meaning": "Netflix营业收入柱状条"},
    {"color": "#8bd4f0", "meaning": "迪士尼娱乐分部营业收入柱状条"},
    {"color": "#e85d45", "meaning": "Netflix同比增长折线及数值"},
    {"color": "#4a90e2", "meaning": "迪士尼娱乐分部同比增长折线及数值"}
  ],
  "visualization_spec": "该可视化采用双轴组合图设计，画布比例约为16:9。背景为纯白色，顶部标题使用粗体黑字与橙色（#fc8166）突出“迪士尼”字样。图表主体分为左右两个Y轴：左侧轴对应柱状图，单位为亿美元，刻度范围0-500；右侧轴对应折线图，单位为百分比%，范围0%-18%。X轴按时间顺序排列FY2022至FY2026五个财年节点。数据展示上，橙色（#fc8166）和浅蓝色（#8bd4f0）的圆角矩形柱状条分别代表Netflix和迪士尼的绝对收入值，数值直接标注于柱顶上方。深红色（#e85d45）和蓝色（#4a90e2）的折线分别连接两家公司的增长率数据点，关键节点旁标注具体百分比数值。图中包含淡灰色水平网格线辅助读数。底部设有灰色背景的数据说明区，解释了不同公司财年统计口径的差异（如2026财年的部分数据）。整体视觉风格简洁明快，通过颜色对比强化了两大流媒体巨头的竞争态势。",
  "key_data_highlights": [
    "FY2025 Netflix收入(452亿)首次超过迪士尼娱乐分部(425亿)",
    "Netflix FY2024-FY2025增速维持在15%以上高位",
    "迪士尼娱乐分部增速从FY2024的低谷(1.36%)回升至FY2026的7.47%",
    "FY2022-FY2024期间迪士尼娱乐分部收入始终领先Netflix"
  ],
  "data_source_text": "数据来源：公司公告"
}
